export function drawMusicPlayer(x,l,cover){const w=l.w,h=l.h,m=l.player,dark=m.theme==='charcoal',bg=dark?'#292d34':m.theme==='rose'?'#e8dfe3':'#e2e7ed',fg=dark?'#d7e0e9':'#37414d',light=dark?'#3a414a':'#ffffff',shadow=dark?'#171a20':'#b7bec9',accent=m.accent||'#a17566',scale=Math.min(w/380,h/520);x.save();x.scale(w/380,h/520);const box=(a,b,c,d,r,fill,raised=true)=>{x.save();x.fillStyle=fill;if(raised){x.shadowBlur=12;x.shadowOffsetX=6;x.shadowOffsetY=6;x.shadowColor=shadow;x.beginPath();x.roundRect(a,b,c,d,r);x.fill();x.shadowOffsetX=-5;x.shadowOffsetY=-5;x.shadowColor=light;x.fill();}x.shadowColor='transparent';x.beginPath();x.roundRect(a,b,c,d,r);x.fill();x.restore();};x.translate(-190,-260);box(8,8,364,504,30,bg,false);x.fillStyle=fg;x.textAlign='center';x.font='10px sans-serif';x.fillText('NOW PLAYING',190,42);box(64,70,252,252,20,bg);if(cover){x.save();x.beginPath();x.roundRect(74,80,232,232,14);x.clip();const size=Math.min(cover.width,cover.height);x.drawImage(cover,(cover.width-size)/2,(cover.height-size)/2,size,size,74,80,232,232);x.restore();}x.fillStyle=fg;x.font='600 21px sans-serif';x.fillText((m.title||'Untitled').slice(0,24),190,359,320);x.globalAlpha=.6;x.font='12px sans-serif';x.fillText((m.artist||'Unknown artist').slice(0,42),190,383,320);x.globalAlpha=1;box(43,408,294,6,3,shadow,false);x.fillStyle=accent;x.beginPath();x.roundRect(43,408,294*(m.progress||0),6,3);x.fill();box(33+294*(m.progress||0),401,20,20,10,bg);x.fillStyle=fg;x.font='10px monospace';x.textAlign='left';const time=n=>Math.floor(n/60)+':'+String(Math.floor(n%60)).padStart(2,'0');x.fillText(time((m.duration||0)*(m.progress||0)),43,433);x.textAlign='right';x.fillText(time(m.duration||0),337,433);for(const [cx,label]of [[108,'−10'],[190,'▶'],[272,'+10']]){box(cx-24,451,48,42,21,bg);x.fillStyle=cx===190?accent:fg;x.textAlign='center';x.font=cx===190?'17px sans-serif':'11px sans-serif';x.fillText(label,cx,478);}x.restore();}
